dogma/grading/static.py:
"""Static checks that run before any learner code executes (ARCHITECTURE §4.2).

Python: the file parses, the entry point is a top-level ``def``/``class``, every import stays
inside the problem's runtime (``py-numpy`` allows the standard library and NumPy, ADR-0021), and
no banned module is imported or reached through attribute access (``np.linalg`` counts). The
banned-import rule is ported from ``scripts/grade.py``. SQL: only a non-empty check.
"""

from __future__ import annotations

import ast
import sys
from collections.abc import Iterable, Sequence
from pathlib import Path
from typing import Literal

from dogma.grading.models import StaticFinding

Language = Literal["python", "sql"]

_FUNCTION_OR_CLASS = (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)
# Test-data helpers and dataset downloads belong to the tests alone (I-31a). This applies to every
# problem, so it is not repeated in each meta.yaml.
PLATFORM_BANNED_IMPORTS = ("dogma_data", "datasets", "huggingface_hub")
_PLATFORM_MESSAGE = "submissions may not import test-data helpers (dogma_data) or download datasets"
# What a submission may import beyond the standard library, per runtime (ADR-0021). Each runtime
# adds to the one before it. A runtime missing here (none in use) has no runtime restriction;
# per-problem ``banned_imports`` apply on top of every runtime.
RUNTIME_IMPORTS: dict[str, frozenset[str]] = {
    "py-stdlib": frozenset(),
    "py-numpy": frozenset({"numpy"}),
    "py-data": frozenset({"numpy", "scipy", "pandas", "sklearn", "statsmodels"}),
    "py-torch": frozenset({"numpy", "scipy", "pandas", "sklearn", "statsmodels", "torch"}),
}
_RUNTIME_WORDS = {
    "py-stdlib": "the Python standard library only",
    "py-numpy": "the Python standard library and NumPy",
    "py-data": "the standard library, NumPy, SciPy, pandas, scikit-learn and statsmodels",
    "py-torch": "the standard library, the py-data libraries and PyTorch",
}


def check_submission(
    path: Path,
    *,
    language: Language,
    entry: str,
    banned_imports: Iterable[str],
    runtime: str | None = None,
) -> list[StaticFinding]:
    """Return every static problem in the submission at ``path``; an empty list means it may run.

    ``runtime`` is the problem's ``meta.yaml`` runtime. ``None`` skips the runtime import rule.
    """
    try:
        source = path.read_text(encoding="utf-8")
    except UnicodeDecodeError:
        return [StaticFinding(rule="syntax", message="the file is not valid UTF-8 text")]
    if language == "sql":
        return _check_sql(source)
    return _check_python(source, entry=entry, banned=tuple(banned_imports), runtime=runtime)


def _check_sql(source: str) -> list[StaticFinding]:
    if not source.strip():
        return [StaticFinding(rule="empty", message="the query file is empty")]
    return []


def _check_python(
    source: str, *, entry: str, banned: Sequence[str], runtime: str | None
) -> list[StaticFinding]:
    try:
        tree = ast.parse(source, filename="submission.py")
    except SyntaxError as exc:
        where = f" (line {exc.lineno})" if exc.lineno is not None else ""
        return [StaticFinding(rule="syntax", message=f"{exc.msg}{where}", line=exc.lineno)]
    except (ValueError, RecursionError, MemoryError) as exc:  # MemoryError: parser stack overflow
        return [StaticFinding(rule="syntax", message=f"cannot parse the file: {exc}")]

    findings: list[StaticFinding] = []
    if not _defines_top_level(tree, entry):
        findings.append(
            StaticFinding(
                rule="missing-entry",
                message=f"define `{entry}` as a top-level function or class",
            )
        )
    findings.extend(_banned_findings(tree, banned))
    findings.extend(_platform_findings(tree))
    findings.extend(_runtime_findings(tree, runtime, banned))
    return findings


def _defines_top_level(tree: ast.Module, entry: str) -> bool:
    return any(isinstance(node, _FUNCTION_OR_CLASS) and node.name == entry for node in tree.body)


def _banned_findings(tree: ast.Module, banned: Sequence[str]) -> list[StaticFinding]:
    return [
        StaticFinding(
            rule="banned-import",
            message=f"`{module}` is not allowed in this problem (line {line})",
            line=line,
        )
        for line, module in sorted(_hits(tree, banned))
    ]


def _platform_findings(tree: ast.Module) -> list[StaticFinding]:
    lines = sorted({line for line, _ in _hits(tree, PLATFORM_BANNED_IMPORTS)})
    return [
        StaticFinding(
            rule="banned-import",
            message=f"{_PLATFORM_MESSAGE} (line {line})",
            line=line,
        )
        for line in lines
    ]


def _runtime_findings(
    tree: ast.Module, runtime: str | None, banned: Sequence[str]
) -> list[StaticFinding]:
    """Imports outside the runtime's libraries. A module a ban already reports is not repeated."""
    if runtime is None or runtime not in RUNTIME_IMPORTS:
        return []
    allowed = RUNTIME_IMPORTS[runtime]
    reported = {name.split(".", 1)[0] for name in (*banned, *PLATFORM_BANNED_IMPORTS)}
    hits: set[tuple[int, str]] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            tops = [alias.name.split(".", 1)[0] for alias in node.names]
        elif isinstance(node, ast.ImportFrom) and node.module and node.level == 0:
            tops = [node.module.split(".", 1)[0]]
        else:
            continue
        for top in tops:
            if top in allowed or top in reported or top in sys.stdlib_module_names:
                continue
            hits.add((node.lineno, top))
    return [
        StaticFinding(
            rule="runtime-import",
            message=(
                f"`{top}` is outside this problem's runtime ({runtime}: "
                f"{_RUNTIME_WORDS[runtime]}) (line {line})"
            ),
            line=line,
        )
        for line, top in sorted(hits)
    ]


def _hits(tree: ast.Module, banned: Sequence[str]) -> set[tuple[int, str]]:
    hits: set[tuple[int, str]] = set()
    for node in ast.walk(tree):
        line = getattr(node, "lineno", None)
        if line is None:
            continue
        for name in _names_used(node):
            for module in banned:
                if _matches(name, module, is_attribute=isinstance(node, ast.Attribute)):
                    hits.add((line, module))
    return hits


def _names_used(node: ast.AST) -> list[str]:
    """Module names an import statement brings in, or the attribute name of an access."""
    if isinstance(node, ast.Import):
        return [alias.name for alias in node.names]
    if isinstance(node, ast.ImportFrom) and node.module:
        return [node.module, *(f"{node.module}.{alias.name}" for alias in node.names)]
    if isinstance(node, ast.Attribute):
        return [node.attr]
    return []


def _matches(name: str, module: str, *, is_attribute: bool) -> bool:
    if not is_attribute:
        return name == module or name.startswith(module + ".")
    # ``np.linalg`` is an attribute access, not an import: match the last component only when
    # the banned name is dotted (``numpy.linalg`` -> ``linalg``). A bare banned name such as
    # ``random`` must not match attributes like ``rng.random`` or ``np.random``.
    return "." in module and name == module.rsplit(".", 1)[-1]

dogma_harness/collector.py:
"""Pytest plugin that records each test's outcome, message, duration and captured stdout.

Outcome per test: the worst of its phases. A failing call is ``fail``; a failing setup or
teardown is ``error``; a skip is ``skip``; a test whose call passed is ``pass``.
"""

from __future__ import annotations

import io
import sys
from collections.abc import Generator, Iterator
from contextlib import contextmanager
from dataclasses import dataclass
from pathlib import Path
from typing import TYPE_CHECKING, Literal

import pytest

from dogma_harness.report import (
    MAX_STDOUT_BYTES,
    HarnessResult,
    TestRecord,
    trim_message,
    trim_tail,
    truncate_stdout,
)

if TYPE_CHECKING:
    from _typeshed import ReadableBuffer

_Outcome = Literal["pass", "fail", "error", "skip"]
_RANK: dict[str, int] = {"pass": 0, "skip": 1, "fail": 2, "error": 3}
_HIDDEN_FILE = "test_hidden.py"
_DROPPED_MARKER = "\n[... output beyond the 64 KB limit was discarded ...]\n"


class _BoundedBuffer(io.BytesIO):
    """A byte sink that keeps its first ``limit`` bytes and discards the rest.

    A print loop therefore costs CPU until the time limit, never memory.
    """

    def __init__(self, limit: int) -> None:
        super().__init__()
        self._limit = limit
        self._kept = 0
        self.dropped = 0

    def write(self, data: ReadableBuffer, /) -> int:
        view = memoryview(data).cast("B")
        keep = min(view.nbytes, self._limit - self._kept)
        if keep > 0:
            super().write(view[:keep])
            self._kept += keep
        self.dropped += view.nbytes - max(keep, 0)
        return view.nbytes


@dataclass
class _Entry:
    nodeid: str
    outcome: str | None = None
    message: str = ""
    duration_s: float = 0.0


def describe_exception(exc: BaseException) -> str:
    """Learner-facing text for a failure: the assertion or exception message, plus notes.

    Hypothesis puts the falsifying example in the notes, so they are kept.
    """
    head = type(exc).__name__
    text = str(exc).strip()
    # AssertionError and pytest.fail() already read as a sentence; other exceptions get a prefix.
    plain = isinstance(exc, AssertionError) or type(exc).__module__.startswith("_pytest")
    message = (text or head) if plain else (f"{head}: {text}" if text else head)
    notes: list[str] = list(getattr(exc, "__notes__", ()))
    return trim_message("\n".join([message, *notes]))


def _phase_outcome(report: pytest.TestReport) -> str | None:
    if report.skipped:
        return "skip"
    if report.failed:
        return "fail" if report.when == "call" else "error"
    if report.when == "call":
        return "pass"
    return None  # a passing setup or teardown says nothing about the verdict


def _test_name(nodeid: str) -> str:
    return nodeid.split("::", 1)[1] if "::" in nodeid else nodeid


def _test_file(nodeid: str) -> Literal["public", "hidden"]:
    return "hidden" if Path(nodeid.split("::", 1)[0]).name == _HIDDEN_FILE else "public"


class Collector:
    """Pytest plugin instance passed to ``pytest.main(plugins=[...])``."""

    def __init__(self) -> None:
        self._entries: dict[str, _Entry] = {}
        self._messages: dict[str, str] = {}
        self._stdout: list[str] = []
        self._stdout_bytes = 0
        self._collection_errors: list[str] = []

    @contextmanager
    def _captured_stdout(self) -> Iterator[None]:
        """Capture ``sys.stdout`` for one phase, in memory and bounded (see ``_BoundedBuffer``)."""
        buffer = _BoundedBuffer(MAX_STDOUT_BYTES)
        stream = io.TextIOWrapper(
            buffer, encoding="utf-8", errors="replace", newline="", write_through=True
        )
        previous = sys.stdout
        sys.stdout = stream
        try:
            yield
        finally:
            sys.stdout = previous
            stream.flush()
            text = buffer.getvalue().decode("utf-8", errors="ignore")
            if buffer.dropped:
                text += _DROPPED_MARKER
            self._add_stdout(text)

    def _add_stdout(self, text: str) -> None:
        if not text or self._stdout_bytes >= MAX_STDOUT_BYTES:
            return
        self._stdout.append(text)
        self._stdout_bytes += len(text.encode("utf-8", errors="replace"))

    @pytest.hookimpl(wrapper=True)
    def pytest_make_collect_report(
        self, collector: pytest.Collector
    ) -> Generator[None, pytest.CollectReport | None, pytest.CollectReport | None]:
        with self._captured_stdout():
            report = yield
        return report

    @pytest.hookimpl(wrapper=True)
    def pytest_runtest_setup(self, item: pytest.Item) -> Generator[None, None, None]:
        with self._captured_stdout():
            yield

    @pytest.hookimpl(wrapper=True)
    def pytest_runtest_call(self, item: pytest.Item) -> Generator[None, None, None]:
        with self._captured_stdout():
            yield

    @pytest.hookimpl(wrapper=True)
    def pytest_runtest_teardown(
        self, item: pytest.Item, nextitem: pytest.Item | None
    ) -> Generator[None, None, None]:
        with self._captured_stdout():
            yield

    @pytest.hookimpl(wrapper=True)
    def pytest_runtest_makereport(
        self, item: pytest.Item, call: pytest.CallInfo[None]
    ) -> Generator[None, pytest.TestReport, pytest.TestReport]:
        report = yield
        if report.failed and call.excinfo is not None:
            # Keep the first failing phase: a setup error is the root cause, not a teardown echo.
            self._messages.setdefault(item.nodeid, describe_exception(call.excinfo.value))
        return report

    def pytest_collectreport(self, report: pytest.CollectReport) -> None:
        if report.failed:
            self._collection_errors.append(str(report.longrepr))

    def pytest_runtest_logreport(self, report: pytest.TestReport) -> None:
        entry = self._entries.setdefault(report.nodeid, _Entry(report.nodeid))
        entry.duration_s += report.duration
        phase = _phase_outcome(report)
        if phase is None:
            return
        if entry.outcome is None or _RANK[phase] > _RANK[entry.outcome]:
            entry.outcome = phase
        if phase in ("fail", "error") and not entry.message:
            entry.message = self._messages.get(report.nodeid, "")

    def result(self, exit_code: int) -> HarnessResult:
        """Turn the recorded state into the report. ``exit_code`` is pytest's own."""
        stdout = truncate_stdout("".join(self._stdout))
        tests = tuple(self._test_records())
        if self._collection_errors:
            text = "\n\n".join(self._collection_errors)
            return HarnessResult("error", tests, stdout, trim_tail(text))
        if not tests:
            return HarnessResult("error", (), stdout, "no tests were collected")
        if exit_code not in (0, 1):
            return HarnessResult(
                "error", tests, stdout, f"pytest stopped early (exit code {exit_code})"
            )
        status: Literal["passed", "failed"] = (
            "passed" if all(t.outcome == "pass" for t in tests) else "failed"
        )
        return HarnessResult(status, tests, stdout, None)

    def _test_records(self) -> list[TestRecord]:
        records: list[TestRecord] = []
        for entry in self._entries.values():
            outcome: _Outcome = _as_outcome(entry.outcome)
            records.append(
                TestRecord(
                    name=_test_name(entry.nodeid),
                    file=_test_file(entry.nodeid),
                    outcome=outcome,
                    message=entry.message,
                    duration_ms=round(entry.duration_s * 1000),
                )
            )
        return records


_OUTCOMES: dict[str, _Outcome] = {"pass": "pass", "fail": "fail", "error": "error", "skip": "skip"}


def _as_outcome(outcome: str | None) -> _Outcome:
    """A test that never finished its call (e.g. the run was aborted) counts as an error."""
    return _OUTCOMES.get(outcome or "", "error")
